func (r *GraphQLRoomRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*projdemov1.Room, string, error) {
	if err := repox.CheckReadMask((*projdemov1.Room)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng, conds, err := r.engine(in, scope...)
	if err != nil {
		return nil, "", err
	}
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*projdemov1.Room, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
// mutable field. When in.Etag is set the write is guarded server-side
// (UpdateIfMatch); a stale etag returns repox.ErrConflict.
func (r *GraphQLRoomRepository) Update(ctx context.Context, in *projdemov1.Room, paths []string) (*projdemov1.Room, error) {
	return r.update(ctx, in, paths, nil)
}

// update is Update's write, with the server-owned fields outputPaths names
// (UpdateWithOutputOnly) merged into its patch.
func (r *GraphQLRoomRepository) update(ctx context.Context, in *projdemov1.Room, paths, outputPaths []string) (*projdemov1.Room, error) {
	ids, err := repox.SplitName(in.GetName(), "rooms")
	if err != nil {
		return nil, err
	}
	id := ids[len(ids)-1]
	row, err := r.Svc.Query.ProjdemoV1.Rooms.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := roomFromRow(row)
	merged := proto.Clone(existingPB).(*projdemov1.Room)
	applyRoomMask(merged, in, paths)
	if h := r.Hooks.BeforeUpdate; h != nil {
		if err := h(ctx, existingPB, merged, paths); err != nil {
			return nil, err
		}
	}
	patch := roomToUpdatePatch(merged)
	resp, err := r.Svc.Mutation.ProjdemoV1.Rooms.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// newInput builds the insert a Batch queues for in, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLRoomRepository) newInput(in *projdemov1.Room) (roomsql.CreateInput, *projdemov1.Room, error) {
	var ci roomsql.CreateInput
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "rooms")
		if err != nil {
			return ci, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*projdemov1.Room)
	in.Name = FormatRoomName(id)
	ci = roomToCreateInput(in)
	ci.Id = id
	return ci, in, nil
}

// updateOps queues Update's writes onto ops, for a Batch: the value-object
// rows that replace the masked ones, the row update, then the removal of what
// they replaced. With in.Etag set the update is guarded inside the batch: a
// self-update of the key whose post-check asserts the etag fails the request
// when the record moved on, and the guarded update after it writes the row.
//
// outputPaths names the server-owned fields written alongside
// (Update<Model>WithOutputOnly); nil for Update.
func (r *GraphQLRoomRepository) updateOps(ctx context.Context, ops *repox.Ops, id string, in *projdemov1.Room, paths, outputPaths []string) (repox.Check, error) {
	row, err := r.Svc.Query.ProjdemoV1.Rooms.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := roomFromRow(row)
	merged := proto.Clone(existingPB).(*projdemov1.Room)
	applyRoomMask(merged, in, paths)
	patch := roomToUpdatePatch(merged)
	var utx, atx repox.Ops
	*ops = append(*ops, utx...)
	resp := new(roomsql.UpdateProjdemoV1RoomsByIdResponse)
	ops.Add(r.Svc.Mutation.ProjdemoV1.Rooms.UpdateOp(id, patch, resp))
	*ops = append(*ops, atx...)
	return func(ctx context.Context, failed error) error {
		if failed == nil {
			if resp.AffectedRows == 0 {
				return repox.ErrNotFound
			}
			return nil
		}
		return nil
	}, nil
}

// Delete removes the record addressed by its resource name.
func (r *GraphQLRoomRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "rooms"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	return r.remove(ctx, id)
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLRoomRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.ProjdemoV1.Rooms.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GraphQLRoomRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*projdemov1.Room, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*projdemov1.Room, string, error) {
		return r.List(ctx, in)
	})
}

